<?php
require_once __DIR__.'/config/config.php';$code=trim($_GET['code']??'');$s=db()->prepare("SELECT cert.certificate_code,cert.issued_at,u.name,c.title FROM certificates cert JOIN users u ON u.id=cert.user_id JOIN courses c ON c.id=cert.course_id WHERE cert.certificate_code=? LIMIT 1");$s->execute([$code]);$cert=$s->fetch();$page_title='Certificate verification — LinguaFree';include __DIR__.'/includes/header.php';?>
<div class="verify-wrap"><span class="eyebrow">LINGUAFREE · PUBLIC VERIFICATION</span><?php if($cert):?><div class="verify-status">✓ VALID CERTIFICATE</div><h1>Certificate verified</h1><p>This certificate record matches our database.</p><dl><dt>Learner</dt><dd><?= e($cert['name']) ?></dd><dt>Course</dt><dd><?= e($cert['title']) ?></dd><dt>Issued</dt><dd><?= e(date('F j, Y',strtotime($cert['issued_at']))) ?></dd><dt>Certificate ID</dt><dd><?= e($cert['certificate_code']) ?></dd></dl><?php else:?><div class="verify-invalid">Certificate not found</div><p>The code may be incorrect or the certificate has not been issued.</p><?php endif;?></div>
